using BusinessPartnerPortal.Api.Data;using BusinessPartnerPortal.Api.Security;using Microsoft.EntityFrameworkCore;
namespace BusinessPartnerPortal.Api.Features.Notifications;
public static class NotificationEndpoints{public static IEndpointRouteBuilder MapNotificationEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/v1/notifications").RequireAuthorization().WithTags("Notifications");
 g.MapGet("/unread-count",async(CurrentUser current,AppDbContext db,CancellationToken ct)=>{var conn=db.Database.GetDbConnection();await conn.OpenAsync(ct);await using var cmd=conn.CreateCommand();cmd.CommandText="SELECT count(*) FROM notification.notifications WHERE user_id=@uid AND is_read=false";var p=cmd.CreateParameter();p.ParameterName="uid";p.Value=current.UserId;cmd.Parameters.Add(p);return Results.Ok(new{count=Convert.ToInt32(await cmd.ExecuteScalarAsync(ct))});});
 g.MapGet("/",async(CurrentUser current,AppDbContext db,CancellationToken ct)=>{var conn=db.Database.GetDbConnection();await conn.OpenAsync(ct);await using var cmd=conn.CreateCommand();cmd.CommandText="SELECT id,title,message,is_read,created_at,action_url FROM notification.notifications WHERE user_id=@uid ORDER BY created_at DESC LIMIT 100";var p=cmd.CreateParameter();p.ParameterName="uid";p.Value=current.UserId;cmd.Parameters.Add(p);var rows=new List<object>();await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add(new{id=r.GetGuid(0),title=r.GetString(1),message=r.GetString(2),isRead=r.GetBoolean(3),createdAt=r.GetFieldValue<DateTimeOffset>(4),actionUrl=r.IsDBNull(5)?null:r.GetString(5)});return Results.Ok(rows);});
 g.MapPut("/{id:guid}/read",async(Guid id,CurrentUser current,AppDbContext db,CancellationToken ct)=>{await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE notification.notifications SET is_read=true,read_at=now(),updated_at=now() WHERE id={id} AND user_id={current.UserId}",ct);return Results.NoContent();});
 g.MapPut("/read-all",async(CurrentUser current,AppDbContext db,CancellationToken ct)=>{await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE notification.notifications SET is_read=true,read_at=now(),updated_at=now() WHERE user_id={current.UserId} AND is_read=false",ct);return Results.NoContent();});return app;}}
